namespace MorphDB.Client.Models;

/// <summary>
/// Request to create a webhook subscription. The signing secret is generated by the service and
/// returned once, in <see cref="WebhookInfo.Secret"/> of the create response.
/// </summary>
public sealed class CreateWebhookRequest
{
    /// <summary>
    /// Webhook name.
    /// </summary>
    public required string Name { get; init; }

    /// <summary>
    /// Table the webhook subscribes to.
    /// </summary>
    public required string Table { get; init; }

    /// <summary>
    /// Webhook delivery URL.
    /// </summary>
    public required string Url { get; init; }

    /// <summary>
    /// Events to subscribe to: <c>insert</c>, <c>update</c>, <c>delete</c>. All three when omitted.
    /// </summary>
    public IReadOnlyList<string>? Events { get; init; }

    /// <summary>
    /// Delivers only rows equal to every entry — field name to a scalar value (string, number, bool or
    /// null). A filter never matches a <c>delete</c>, which carries no row.
    /// </summary>
    public IDictionary<string, object?>? Filter { get; init; }

    /// <summary>
    /// Headers sent with every delivery.
    /// </summary>
    public IDictionary<string, string>? Headers { get; init; }
}

/// <summary>
/// Webhook information response.
/// </summary>
public sealed class WebhookInfo
{
    /// <summary>
    /// Webhook ID.
    /// </summary>
    public Guid Id { get; init; }

    /// <summary>
    /// Webhook name.
    /// </summary>
    public required string Name { get; init; }

    /// <summary>
    /// Table the webhook subscribes to.
    /// </summary>
    public required string Table { get; init; }

    /// <summary>
    /// Webhook delivery URL.
    /// </summary>
    public required string Url { get; init; }

    /// <summary>
    /// The signing secret — present only in the response that created the webhook (or regenerated
    /// its secret); a webhook read back later carries none.
    /// </summary>
    public string? Secret { get; init; }

    /// <summary>
    /// Subscribed events.
    /// </summary>
    public IReadOnlyList<string> Events { get; init; } = [];

    /// <summary>
    /// The delivery filter, if any.
    /// </summary>
    public IDictionary<string, object?>? Filter { get; init; }

    /// <summary>
    /// Headers sent with every delivery, if any.
    /// </summary>
    public IDictionary<string, string>? Headers { get; init; }

    /// <summary>
    /// Whether the webhook is active.
    /// </summary>
    public bool IsActive { get; init; }

    /// <summary>
    /// Creation timestamp.
    /// </summary>
    public DateTimeOffset CreatedAt { get; init; }

    /// <summary>
    /// Last update timestamp.
    /// </summary>
    public DateTimeOffset UpdatedAt { get; init; }
}

/// <summary>
/// One delivery attempt record of a webhook.
/// </summary>
public sealed class WebhookDelivery
{
    /// <summary>
    /// Delivery ID.
    /// </summary>
    public Guid Id { get; init; }

    /// <summary>
    /// Record that triggered the delivery.
    /// </summary>
    public Guid? RecordId { get; init; }

    /// <summary>
    /// Event type.
    /// </summary>
    public required string Event { get; init; }

    /// <summary>
    /// Delivery status.
    /// </summary>
    public required string Status { get; init; }

    /// <summary>
    /// Number of delivery attempts.
    /// </summary>
    public int AttemptCount { get; init; }

    /// <summary>
    /// HTTP status code from the last attempt.
    /// </summary>
    public int? HttpStatusCode { get; init; }

    /// <summary>
    /// Error message from the last attempt.
    /// </summary>
    public string? ErrorMessage { get; init; }

    /// <summary>
    /// Creation timestamp.
    /// </summary>
    public DateTimeOffset CreatedAt { get; init; }

    /// <summary>
    /// Delivery timestamp.
    /// </summary>
    public DateTimeOffset? DeliveredAt { get; init; }
}
